```js
const EPS = 1e-6;

function sweptHit(px, py, dx, dy, brick) {
  const x0 = brick.x - BALL_R;
  const x1 = brick.x + brick.w + BALL_R;
  const y0 = brick.y - BALL_R;
  const y1 = brick.y + brick.h + BALL_R;

  // The ball already overlaps the brick at the start of the step: resolve by
  // minimal penetration, pushing it out through the nearest face.
  if (px > x0 && px < x1 && py > y0 && py < y1) {
    const penX = Math.min(px - x0, x1 - px);
    const penY = Math.min(py - y0, y1 - py);
    if (penX < penY) {
      const x = px - x0 <= x1 - px ? x0 - EPS : x1 + EPS;
      return { t: 0, flipX: true, flipY: false, x, y: py, brick };
    }
    if (penY < penX) {
      const y = py - y0 <= y1 - py ? y0 - EPS : y1 + EPS;
      return { t: 0, flipX: false, flipY: true, x: px, y, brick };
    }
    const x = px - x0 <= x1 - px ? x0 - EPS : x1 + EPS;
    const y = py - y0 <= y1 - py ? y0 - EPS : y1 + EPS;
    return { t: 0, flipX: true, flipY: true, x, y, brick };
  }

  // Swept slab test: the ball center is a point, the brick is grown by BALL_R.
  let tXin = -Infinity, tXout = Infinity;
  if (dx === 0) {
    if (px < x0 || px > x1) return null;
  } else {
    let t1 = (x0 - px) / dx;
    let t2 = (x1 - px) / dx;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    tXin = t1; tXout = t2;
  }
  let tYin = -Infinity, tYout = Infinity;
  if (dy === 0) {
    if (py < y0 || py > y1) return null;
  } else {
    let t1 = (y0 - py) / dy;
    let t2 = (y1 - py) / dy;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    tYin = t1; tYout = t2;
  }
  if (tXin > tXout || tYin > tYout) return null;
  const tIn = Math.max(0, tXin, tYin);
  const tOut = Math.min(1, tXout, tYout);
  if (tIn > tOut || tOut <= 0 || tIn > 1) return null;

  let flipX = false, flipY = false;
  if (tYin === -Infinity) flipX = true;                       // horizontal path, dx ≠ 0
  else if (tXin === -Infinity) flipY = true;                  // vertical path, dy ≠ 0
  else if (Math.abs(tXin - tYin) < 1e-9) { flipX = true; flipY = true; }  // corner
  else if (tXin > tYin) flipX = true;                         // entered through a side face
  else flipY = true;                                          // entered through the top/bottom face

  const x = flipX ? (dx > 0 ? x0 - EPS : x1 + EPS) : px + dx * tIn;
  const y = flipY ? (dy > 0 ? y0 - EPS : y1 + EPS) : py + dy * tIn;
  return { t: tIn, flipX, flipY, x, y, brick };
}
