    if (best.flipY && !flippedY) { ball.vy = -ball.vy; flippedY = true; }
    if (best.brick.alive) {
      best.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(best.brick, state.combo);
    }
    remaining -= hitTime;
    prevX = ball.x;
    prevY = ball.y;
