// probe.test.js — playtest probe (removed after the investigation).
//
// Runs the six defect cases against the REAL game code (red today), and,
// with NAIVE=1, against a naive "flip vy per overlapped brick, no push-out,
// no sweep" variant (red for the discriminating cases).
//
//   node --test .scratch/probe.test.js          → red against neon.js as-is
//   NAIVE=1 node --test .scratch/probe.test.js  → red against the naive fix

import { test } from 'node:test';
import assert from 'node:assert/strict';

import * as neon from '../game/neon.js';

// --- Naive variant of step(): flips vy for every overlapped brick at the
// endpoint, with no push-out, no face-axis choice, no swept segment. This is
// the "correction naïve" that each discriminating case must refuse.
function naiveStep(state, dt) {
  const { ball, paddle } = state;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (neon.collides(ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += neon.scoreForBrick(brick, state.combo);
      ball.vy = -ball.vy; // flip vy for EVERY overlapped brick, no reposition
    }
  }

  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > neon.WIDTH) {
    ball.x = neon.WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = neon.ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }
  if (ball.y - ball.r > neon.HEIGHT) return true;
  return false;
}

const step = process.env.NAIVE ? naiveStep : neon.step;

// D1 — root cause: the ball never bounces off bricks (frame() kills the brick
// but never deflects the ball). Level 1, ball below the bottom row, moving up.
test('D1: ball hitting a brick from below bounces down at the face', () => {
  const state = neon.createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  assert.ok(brick, 'row 4, col 3 brick exists');
  state.ball = { x: 280, y: 195, r: neon.BALL_R, vx: 0, vy: -neon.ballSpeed(1) };

  const lost = step(state, 0.05);

  assert.equal(lost, false);
  assert.ok(state.ball.vy > 0, `vy=${state.ball.vy} should be > 0 (bounced down)`);
  assert.ok(Math.abs(state.ball.y - 187) < 1e-3, `ball.y=${state.ball.y} should sit at the bottom face (187)`);
  assert.equal(brick.alive, false, 'brick should be broken');
  assert.equal(state.combo, 1);
  assert.equal(state.score, 15); // 10 pts * comboMultiplier(1)
});

// D2 — face vs coin: a side hit must flip vx and leave vy alone.
test('D2: side hit flips vx, not vy', () => {
  const state = neon.createState(1);
  state.bricks = [{ x: 4, y: 76, w: neon.BRICK_W, h: neon.BRICK_H, row: 1, alive: true, points: 40 }];
  const brick = state.bricks[0];
  state.ball = { x: 85, y: 86, r: neon.BALL_R, vx: -300, vy: 0 };

  step(state, 0.05);

  assert.ok(state.ball.vx > 0, `vx=${state.ball.vx} should be > 0 (bounced right)`);
  assert.equal(state.ball.vy, 0, 'vy must not flip on a side hit');
  assert.equal(brick.alive, false);
  assert.ok(!neon.collides(state.ball, brick));
});

// D3 — double inversion: the ball centred on a grid seam overlaps two bricks
// of the same row (8px gap < 14px ball). Two vy flips would cancel and let the
// ball through the seam; it must flip exactly once.
test('D3: seam hit flips vy exactly once (no ghost double inversion)', () => {
  const state = neon.createState(1);
  const left = state.bricks.find((b) => b.row === 0 && b.x === 244);  // col 3
  const right = state.bricks.find((b) => b.row === 0 && b.x === 324); // col 4
  state.ball = { x: 320, y: 35, r: neon.BALL_R, vx: 0, vy: neon.ballSpeed(1) };

  step(state, 0.05);

  assert.ok(state.ball.vy < 0, `vy=${state.ball.vy} should be < 0 (bounced up once)`);
  assert.ok(!left.alive || !right.alive, 'at least one seam brick breaks');
  assert.equal(state.combo, 1, 'the seam pass counts as exactly one hit');
});

// D4 — tunneling: at level 6 the per-step travel (35.5px at dt=0.05) exceeds
// the ball-expanded brick band (34px): a ball can jump from one side of the
// brick to the other within one step without any endpoint overlap. Only a
// swept test sees the hit.
test('D4: ball crossing a brick within one step still bounces (swept)', () => {
  const state = neon.createState(6);
  state.bricks = [{ x: 244, y: 76, w: neon.BRICK_W, h: neon.BRICK_H, row: 1, alive: true, points: 40 }];
  const brick = state.bricks[0];
  state.ball = { x: 280, y: 103.5, r: neon.BALL_R, vx: 0, vy: -neon.ballSpeed(6) };

  step(state, 0.05);

  assert.ok(state.ball.vy > 0, `vy=${state.ball.vy} should be > 0 (bounced off the bottom face)`);
  assert.ok(Math.abs(state.ball.y - 103) < 1e-3, `ball.y=${state.ball.y} should sit at the bottom face (103)`);
  assert.equal(brick.alive, false, 'brick should be broken');
});

// D5 — collant: a ball that starts a step overlapping a brick must be pushed
// out of the rectangle (invariant: after resolution the ball is outside), not
// merely have its velocity flipped.
test('D5: overlapping ball is pushed out of the brick (no sticking)', () => {
  const state = neon.createState(1);
  state.bricks = [{ x: 244, y: 76, w: neon.BRICK_W, h: neon.BRICK_H, row: 1, alive: true, points: 40 }];
  const brick = state.bricks[0];
  state.ball = { x: 280, y: 72, r: neon.BALL_R, vx: 0, vy: neon.ballSpeed(1) };

  step(state, 0.05);

  assert.ok(state.ball.vy < 0, `vy=${state.ball.vy} should be < 0 (bounced up)`);
  assert.ok(!neon.collides(state.ball, brick), 'ball must end outside the brick');
});

// D6 — face vs coin (corner): entering the corner with equal penetration on
// both axes must flip BOTH velocity components.
test('D6: corner hit with equal penetration flips vx AND vy', () => {
  const state = neon.createState(1);
  state.bricks = [{ x: 244, y: 76, w: neon.BRICK_W, h: neon.BRICK_H, row: 1, alive: true, points: 40 }];
  const brick = state.bricks[0];
  state.ball = { x: 230, y: 62, r: neon.BALL_R, vx: 250, vy: 250 };

  step(state, 0.05);

  assert.ok(state.ball.vx < 0, `vx=${state.ball.vx} should be < 0 (corner flips vx)`);
  assert.ok(state.ball.vy < 0, `vy=${state.ball.vy} should be < 0 (corner flips vy)`);
  assert.equal(brick.alive, false);
  assert.ok(!neon.collides(state.ball, brick));
});

