// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The bounce itself lives in resolveBricks().
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves ball-vs-brick collisions for one time step: breaks the brick,
// scores it exactly like the old frame() loop (alive → combo += 1 →
// score += scoreForBrick(brick, combo)) and bounces the ball.
// The bounce axis is the axis of smallest penetration (face vs corner: equal
// penetration is a corner and flips both components); the ball is pushed back
// out of the brick so it can never stick inside it.
function resolveBricks(state) {
  const { ball, bricks } = state;
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;

    const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w + ball.r - ball.x);
    const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h + ball.r - ball.y);

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    if (penX < penY) {
      ball.vx = -ball.vx;
      ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    } else if (penY < penX) {
      ball.vy = -ball.vy;
      ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    } else {
      // Corner: both faces touched at equal depth — both axes flip.
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
      ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }
  }
}

