// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle AND the bricks (resolveBricks).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Bricks: bounce, break + score (moved out of frame(), where it used to be
  // entangled with rendering).
  resolveBricks(state);

