// Resolves ball-vs-brick collisions for one time step: breaks the brick,
// scores it exactly like the old frame() loop (alive → combo += 1 →
// score += scoreForBrick(brick, combo)) and bounces the ball.
//
// Detection is a SWEPT test: the segment [prev, ball] is swept against every
// brick grown by the ball radius (slab method). A ball that crosses a whole
// brick within one step (per-step travel > BRICK_H + 2×BALL_R, reachable from
// level 6 at the 50 ms dt cap) still registers a hit at its entry face. This
// is also what keeps the result independent of dt.
//
// Hits are resolved in order of increasing entry time (first contact wins),
// with at most ONE flip per axis per pass: two same-row bricks overlapped
// through the 8 px grid seam would otherwise each flip vy and cancel out.
function resolveBricks(state, prevX, prevY, dt) {
  const { ball, bricks } = state;
  let remaining = dt;
  let flippedX = false;
  let flippedY = false;
  let guard = 0;

  while (remaining > 0 && guard++ < 8) {
    const dx = ball.vx * remaining;
    const dy = ball.vy * remaining;
    let best = null;

    for (const brick of bricks) {
      if (!brick.alive) continue;
      const hit = sweptHit(prevX, prevY, dx, dy, brick);
      if (hit && (best === null || hit.t < best.t)) best = hit;
    }
    if (!best) break;

    const hitTime = best.t * remaining;
    ball.x = best.x;
    ball.y = best.y;
    if (best.flipX && !flippedX) {
      ball.vx = -ball.vx;
      flippedX = true;
    }
    if (best.flipY && !flippedY) {
      ball.vy = -ball.vy;
      flippedY = true;
    }

    if (best.brick.alive) {
      best.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(best.brick, state.combo);
    }

    remaining -= hitTime;
    prevX = ball.x;
    prevY = ball.y;
  }
}

// Sweeps the ball center (treated as a point) along the segment from (px, py)
// by (dx, dy) against the brick grown by BALL_R. Returns the first contact as
// { t, flipX, flipY, x, y, brick }, or null.
// - If the ball already overlaps the brick at the start of the step, the
//   resolution is the axis of SMALLEST penetration (face vs corner; equal
//   penetration is a corner and flips both axes), pushing the ball out.
// - Otherwise the slab test gives the entry time per axis: the face entered
//   LAST is the face hit; equal entry times mean a corner.
// The returned position sits a hair OUTSIDE the face (EPS) so the ball never
// starts the next step still touching the brick.
const EPS = 1e-6;

function sweptHit(px, py, dx, dy, brick) {
  const x0 = brick.x - BALL_R;
  const x1 = brick.x + brick.w + BALL_R;
  const y0 = brick.y - BALL_R;
  const y1 = brick.y + brick.h + BALL_R;

  if (px > x0 && px < x1 && py > y0 && py < y1) {
    const penX = Math.min(px - x0, x1 - px);
    const penY = Math.min(py - y0, y1 - py);
    if (penX < penY) {
      return { t: 0, flipX: true, flipY: false, x: px - x0 <= x1 - px ? x0 - EPS : x1 + EPS, y: py, brick };
    }
    if (penY < penX) {
      return { t: 0, flipX: false, flipY: true, x: px, y: py - y0 <= y1 - py ? y0 - EPS : y1 + EPS, brick };
    }
    const x = px - x0 <= x1 - px ? x0 - EPS : x1 + EPS;
    const y = py - y0 <= y1 - py ? y0 - EPS : y1 + EPS;
    return { t: 0, flipX: true, flipY: true, x, y, brick };
  }

  let tXin = -Infinity;
  let tXout = Infinity;
  if (dx === 0) {
    if (px < x0 || px > x1) return null;
  } else {
    let t1 = (x0 - px) / dx;
    let t2 = (x1 - px) / dx;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    tXin = t1;
    tXout = t2;
  }

  let tYin = -Infinity;
  let tYout = Infinity;
  if (dy === 0) {
    if (py < y0 || py > y1) return null;
  } else {
    let t1 = (y0 - py) / dy;
    let t2 = (y1 - py) / dy;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    tYin = t1;
    tYout = t2;
  }

  if (tXin > tXout || tYin > tYout) return null;
  const tIn = Math.max(0, tXin, tYin);
  const tOut = Math.min(1, tXout, tYout);
  // tOut <= 0: the segment only touches the band at its start and moves away.
  if (tIn > tOut || tOut <= 0 || tIn > 1) return null;

  let flipX = false;
  let flipY = false;
  if (tYin === -Infinity) {
    flipX = true; // horizontal path
  } else if (tXin === -Infinity) {
    flipY = true; // vertical path
  } else if (Math.abs(tXin - tYin) < 1e-9) {
    flipX = true; // corner: both faces entered at the same instant
    flipY = true;
  } else if (tXin > tYin) {
    flipX = true; // the side face was entered last
  } else {
    flipY = true; // the top/bottom face was entered last
  }

  const x = flipX ? (dx > 0 ? x0 - EPS : x1 + EPS) : px + dx * tIn;
  const y = flipY ? (dy > 0 ? y0 - EPS : y1 + EPS) : py + dy * tIn;
  return { t: tIn, flipX, flipY, x, y, brick };
}

