export function step(state, dt) {
  const { ball, paddle } = state;

  // Bricks, part 1: swept bounce/break/score along the pre-clamp path
  // (moved out of frame(), where it used to be entangled with rendering).
  // prevX/prevY let resolveBricks sweep the ball's path so a fast ball cannot
  // tunnel through a brick in one step.
  const prevX = ball.x;
  const prevY = ball.y;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;
  resolveBricks(state, prevX, prevY, dt);

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks, part 2: the wall/ceiling clamps snap the ball back into the field;
  // a fast ball hugging a wall can end that snap inside a brick's band, so
  // resolve again (t=0 minimal-penetration push-out + bounce) from the clamped
  // position.
  resolveBricks(state, ball.x, ball.y, dt);

