// The returned position sits a hair OUTSIDE the face (EPS) so the ball never
// starts the next step still touching the brick.
const EPS = 1e-6;

function sweptHit(px, py, dx, dy, brick) {
  const x0 = brick.x - BALL_R;
  const x1 = brick.x + brick.w + BALL_R;
  const y0 = brick.y - BALL_R;
  const y1 = brick.y + brick.h + BALL_R;

  if (px > x0 && px < x1 && py > y0 && py < y1) {
    const penX = Math.min(px - x0, x1 - px);
    const penY = Math.min(py - y0, y1 - py);
    if (penX < penY) {
      return { t: 0, flipX: true, flipY: false, x: px - x0 <= x1 - px ? x0 - EPS : x1 + EPS, y: py, brick };
    }
    if (penY < penX) {
      return { t: 0, flipX: false, flipY: true, x: px, y: py - y0 <= y1 - py ? y0 - EPS : y1 + EPS, brick };
    }
    const x = px - x0 <= x1 - px ? x0 - EPS : x1 + EPS;
    const y = py - y0 <= y1 - py ? y0 - EPS : y1 + EPS;
    return { t: 0, flipX: true, flipY: true, x, y, brick };
  }

  let tXin = -Infinity;
  let tXout = Infinity;
  if (dx === 0) {
    if (px < x0 || px > x1) return null;
  } else {
    let t1 = (x0 - px) / dx;
    let t2 = (x1 - px) / dx;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    tXin = t1;
    tXout = t2;
  }

  let tYin = -Infinity;
  let tYout = Infinity;
  if (dy === 0) {
    if (py < y0 || py > y1) return null;
  } else {
    let t1 = (y0 - py) / dy;
    let t2 = (y1 - py) / dy;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    tYin = t1;
    tYout = t2;
  }

  if (tXin > tXout || tYin > tYout) return null;
  const tIn = Math.max(0, tXin, tYin);
  const tOut = Math.min(1, tXout, tYout);
  // tOut <= 0: the segment only touches the band at its start and moves away.
  if (tIn > tOut || tOut <= 0 || tIn > 1) return null;

  let flipX = false;
  let flipY = false;
  if (tYin === -Infinity) {
    flipX = true; // horizontal path
  } else if (tXin === -Infinity) {
    flipY = true; // vertical path
  } else if (Math.abs(tXin - tYin) < 1e-9) {
    flipX = true; // corner: both faces entered at the same instant
    flipY = true;
  } else if (tXin > tYin) {
    flipX = true; // the side face was entered last
  } else {
    flipY = true; // the top/bottom face was entered last
  }

  const x = flipX ? (dx > 0 ? x0 - EPS : x1 + EPS) : px + dx * tIn;
  const y = flipY ? (dy > 0 ? y0 - EPS : y1 + EPS) : py + dy * tIn;
  return { t: tIn, flipX, flipY, x, y, brick };
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;

